 private void refresh(){if(prefs==null)return;boolean on=prefs.getBoolean("bot_enabled",false),bi=isBusinessInstalled(),ac=WhatsAppAccessibilityService.isEnabled(this),no=isNotificationAccessEnabled();set(wa,bi?"ATIVO":"OFF",bi);set(acc,ac?"ATIVA":"OFF",ac);set(notif,no?"ATIVAS":"OFF",no);set(engine,on?"ATIVO":"PAUSADO",on);if(mode!=null){mode.setText(on?"MODO ATUAL:  AUTOMÁTICO":"MODO ATUAL:  PAUSADO");mode.setTextColor(on?GREEN:RED);}if(power!=null){power.active=on;power.invalidate();}if(online!=null){online.setText(on?"● ONLINE":"● PAUSADO");online.setTextColor(on?GREEN:RED);}setValue(lastChat,prefs.getString("accessibility_last_conversation",""));setValue(lastMsg,prefs.getString("accessibility_last_message",""));setValue(lastReply,prefs.getString("accessibility_last_reply",""));setValue(lastStatus,prefs.getString("accessibility_last_status",""));int p=prefs.getInt("neon_pending_replies",0),s=prefs.getInt("stats_sent_today",0),f=prefs.getInt("stats_failed_today",0),a=prefs.getInt("stats_attempts_today",0),t=prefs.getInt("stats_chats_today",0);if(pending!=null)pending.setText("• Pendentes     "+p);if(sent!=null)sent.setText("• Enviadas       "+s);if(fail!=null)fail.setText("• Falhas            "+f);if(attempts!=null)attempts.setText("• Tentativas     "+a);if(today!=null)today.setText("• Atendimentos          "+t);if(totalSent!=null)totalSent.setText("• Respostas enviadas  "+s);if(rate!=null)rate.setText("• Taxa de sucesso       "+((s+f)==0?"--":Math.round(100f*s/(s+f))+"%"));if(totalFail!=null)totalFail.setText("• Falhas                     "+f);}
 private class PowerView extends View{Paint p=new Paint(1);boolean active=true;PowerView(){super(NeonDashboardActivity.this);setLayerType(View.LAYER_TYPE_SOFTWARE,null);}protected void onDraw(Canvas c){super.onDraw(c);float w=getWidth(),h=getHeight(),cx=w/2,cy=h/2,r=Math.min(w,h)*.42f;int co=active?GREEN:RED;p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(3));p.setColor(co);p.setShadowLayer(dp(12),0,0,co);c.drawCircle(cx,cy,r,p);p.setShadowLayer(0,0,0,0);p.setStrokeWidth(dp(5));RectF a=new RectF(cx-r*.46f,cy-r*.46f,cx+r*.46f,cy+r*.46f);c.drawArc(a,-45,270,false,p);c.drawLine(cx,cy-r*.58f,cx,cy+r*.05f,p);}}
