 private class RingView extends View{Paint p=new Paint(1);int color;String mark;RingView(int c,String m){super(NeonDashboardActivity.this);color=c;mark=m;}protected void onDraw(Canvas c){float x=getWidth()/2f,y=getHeight()/2f,r=Math.min(x,y)*.72f;p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(3));p.setColor(Color.rgb(30,45,55));c.drawCircle(x,y,r,p);p.setColor(color);c.drawArc(new RectF(x-r,y-r,x+r,y+r),-80,230,false,p);p.setStyle(Paint.Style.FILL);p.setTextSize(dp(22));p.setTextAlign(Paint.Align.CENTER);c.drawText(mark,x,y+dp(7),p);}}
 private void setValue(TextView v,String s){if(v!=null)v.setText(value(s));} private TextView service(LinearLayout p,String icon,String label,int accent){LinearLayout c=col();c.setGravity(Gravity.CENTER);c.setPadding(dp(3),dp(8),dp(3),dp(8));c.setBackground(bg(CARD,Color.rgb(35,55,65),9,1));TextView i=text(icon,25,accent,true);i.setGravity(Gravity.CENTER);i.setShadowLayer(8,0,0,accent);c.addView(i);TextView l=text(label,9,Color.WHITE,true);l.setGravity(Gravity.CENTER);c.addView(l);TextView state=text("...",9,GREEN,true);state.setGravity(Gravity.CENTER);c.addView(state);p.addView(c,new LinearLayout.LayoutParams(0,dp(118),1f));p.addView(spaceH(7));return state;} private TextView activityRow(LinearLayout p,String icon,String label){LinearLayout r=row();r.addView(text(icon,12,CYAN,true),new LinearLayout.LayoutParams(dp(22),-2));r.addView(text(label,10,MUTED,false),new LinearLayout.LayoutParams(dp(118),-2));TextView v=text("—",10,Color.WHITE,true);r.addView(v,new LinearLayout.LayoutParams(0,-2,1f));p.addView(r);p.addView(space(6));return v;} private TextView metric(LinearLayout p,String s){TextView t=text("• "+s,9,Color.WHITE,false);t.setPadding(0,dp(6),0,0);p.addView(t);return t;} private Button action(String s,int c){Button b=new Button(this);b.setText(s);b.setTextSize(10);b.setTextColor(Color.WHITE);b.setTypeface(Typeface.DEFAULT_BOLD);b.setAllCaps(false);b.setBackground(bg(Color.rgb(5,16,12),c,8,2));return b;} private Button nav(String s,int c,View.OnClickListener l){Button b=new Button(this);b.setText(s);b.setTextSize(9);b.setTextColor(c);b.setAllCaps(false);b.setBackgroundColor(Color.TRANSPARENT);b.setOnClickListener(l);return b;} private LinearLayout card(int stroke){LinearLayout l=col();l.setPadding(dp(11),dp(11),dp(11),dp(11));l.setBackground(bg(CARD,stroke,9,1));return l;} private void title(LinearLayout r,String s){r.addView(space(14));r.addView(text(s,11,Color.WHITE,true));r.addView(space(7));} private void set(TextView v,String s,boolean ok){if(v!=null){v.setText(s);v.setTextColor(ok?GREEN:RED);}} private boolean isBusinessInstalled(){try{getPackageManager().getPackageInfo("com.whatsapp.w4b",0);return true;}catch(Throwable t){return false;}} private boolean isNotificationAccessEnabled(){try{String e=Settings.Secure.getString(getContentResolver(),"enabled_notification_listeners");return e!=null&&e.contains(getPackageName());}catch(Throwable t){return false;}} private GradientDrawable bg(int fill,int stroke,int radius,int width){GradientDrawable d=new GradientDrawable();d.setColor(fill);d.setCornerRadius(dp(radius));d.setStroke(dp(width),stroke);return d;} private GradientDrawable circle(int fill,int stroke,int width){GradientDrawable d=bg(fill,stroke,100,width);d.setShape(GradientDrawable.OVAL);return d;} private LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;} private LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER_VERTICAL);return l;} private TextView text(String s,int sp,int c,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(sp);t.setTextColor(c);t.setTypeface(Typeface.DEFAULT,bold?Typeface.BOLD:Typeface.NORMAL);return t;} private Space space(int x){Space s=new Space(this);s.setLayoutParams(new LinearLayout.LayoutParams(1,dp(x)));return s;} private Space spaceH(int x){Space s=new Space(this);s.setLayoutParams(new LinearLayout.LayoutParams(dp(x),1));return s;} private LinearLayout.LayoutParams weight(){return new LinearLayout.LayoutParams(0,dp(58),1f);} private String value(String s){if(s==null||s.trim().isEmpty())return"—";s=s.trim();return s.length()>52?s.substring(0,49)+"...":s;} private int dp(int x){return Math.round(x*getResources().getDisplayMetrics().density);}
